/* Service a PD interrupt (the FUSB302B INT is wire-ORed into SC_INT_N */
/* with the TCA9535 INT# -- read BOTH status registers on the IRQ).    */
void sc_pd_on_irq(void);

#endif /* SC_PD_H */
